INSERT INTO public.exercises (name_en, name_es, category, muscle, equipment, instructions_en, instructions_es)
VALUES 
('Barbell Bench Press', 'Press de Banca con Barra', 'strength', 'chest', 'barbell', '1. Lie on a flat bench.\n2. Grasp the barbell.\n3. Lower the bar to your chest.\n4. Press it back up.', '1. Acuéstate en un banco plano.\n2. Agarra la barra.\n3. Baja la barra hasta el pecho.\n4. Empújala hacia arriba.'),
('Dumbbell Curl', 'Curl de Bíceps con Mancuerna', 'strength', 'biceps', 'dumbbell', '1. Stand up straight with a dumbbell in each hand.\n2. Curl the weights while contracting your biceps.', '1. Ponte de pie con una mancuerna en cada mano.\n2. Levanta el peso mientras contraes los bíceps.'),
('Squat', 'Sentadilla', 'strength', 'quadriceps', 'barbell', '1. Stand with feet shoulder-width apart.\n2. Lower your body as if sitting in a chair.\n3. Keep your back straight.', '1. Párate con los pies separados a la altura de los hombros.\n2. Baja el cuerpo como si te sentaras en una silla.\n3. Mantén la espalda recta.'),
('Pull-up', 'Dominadas', 'strength', 'lats', 'body_only', '1. Grab the pull-up bar.\n2. Pull yourself up until your chin passes the bar.', '1. Agarra la barra de dominadas.\n2. Sube hasta que tu barbilla pase la barra.');
